    type Error = u64;

    /// Decode a type-tag, or hand back one that names no kind.
    fn try_from(type_tag: u64) -> Result<Self, u64> {
        match type_tag {
            1 => Ok(Kind::Ping),
            2 => Ok(Kind::Text),
            3 => Ok(Kind::Blob),
            _ => Err(type_tag),
        }
    }
