    /// `table[i]`, [`NO_SEGMENT`] past `seg_count`, segment 0's
    /// only.
    table: CacheAligned<[AtomicU32; MAX_SEGMENTS as usize]>,
}

const _: () = assert!(size_of::<SegmentHeader>() == 4 * CACHE_LINE_SIZE);

