        (r.0.as_mut_ptr(), r.0.len())
    }

    /// Initialize the test pool over `base` and run `f` on it,
    /// dropping the handle after.
    fn with_init_pool<R>(base: *mut u8, len: usize, f: impl FnOnce(&mut Pool<'_>) -> R) -> R {
